/* ==========================================================================
   WORKSHEETS: HER DAILY PRACTICE SHEETS
   ==========================================================================
   Clearance & Elimination Practice 1–4 and Single Oral Practice 1–3, each
   stem as she printed it and each line of working from her solution key.
   Written by src/gen/ws_practice.py (run it, not this file), which recomputes every answer from the
   stem and fails if the keyed value is outside the tolerance. Where her key's
   last digit comes from an unrounded intermediate, `note` says so and the
   tolerance accepts both.
   ========================================================================== */
const Q_WORKSHEETS = [
{"id": "ws4-1-crcl", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "crclcalc", "concept": "cockcroft-gault", "skill": "crcl", "source": "slide", "stem": "Estimate the CrCl of a 36-year-old male who weighs 160 lb, SCr =0.8 mg/dL, and 68” tall.", "units": "mL/min", "answer": 123.5, "tol": 1.2, "steps": [{"k": "unit", "t": "68 in − 60 in = 8 inches over 5 ft", "why": "The ideal body weight equation counts only the inches above five feet, so 60 inches are subtracted from the height."}, {"k": "algebra", "t": "IBW = 50 + 2.3(8) = 68.4 kg", "why": "The male form starts at 50 kg. The 160 lb total body weight is not used, because her keys use ideal body weight."}, {"k": "setup", "t": "CrCl = {{frac:(140 − 36)(68.4)|(72)(0.8)}}", "why": "This is the Cockcroft-Gault equation; the patient is male, so the 0.85 factor for a female patient is not applied."}, {"k": "round", "t": "CrCl = 123.5 mL/min", "why": "The result is reported to one decimal place in mL/min, the unit creatinine clearance is always given in."}], "teach": [{"h": "The method, in order", "list": ["Height in centimetres: divide by 2.54 to get inches, then count the inches over 60 (5 ft).", "Ideal body weight (IBW): male 50 + 2.3 × (inches over 5 ft); female 45.5 + 2.3 × (inches over 5 ft).", "CrCl = {{frac:(140 − age)(IBW)|72 × SCr}}, then × 0.85 if the patient is female.", "Her keys use IBW, not the weight given in the stem.", "Report CrCl in mL/min. It estimates the glomerular filtration rate (GFR), about 120 mL/min in a healthy adult."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 1, first problem"},
{"id": "ws4-1a", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "thalf-from-cl-vd", "skill": "krate", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. Calculate the half-life of the agent.", "units": "hr", "answer": 12.5, "tol": 0.12, "steps": [{"k": "setup", "t": "t½ = {{frac:0.693 VD|Cl}}", "why": "Cl = k × VD and k = {{frac:0.693|t½}} combined give t½ = 0.693 {{frac:VD|Cl}}, so the half-life comes straight from volume and clearance."}, {"k": "algebra", "t": "t½ = {{frac:0.693(9 L)|0.5 L/hr}} = 12.5 hr", "why": "Litres in the numerator cancel with the litres in L/hr, leaving hours, the unit of a half-life."}], "teach": [{"h": "Half-life from clearance and volume", "list": ["Cl = k × VD (one of the equations she expects without the sheet).", "k = {{frac:0.693|t½}}, so t½ = {{frac:0.693 VD|Cl}}.", "A larger volume or a smaller clearance gives a longer half-life.", "Keep the units matched: L with L/hr gives hours; mL with mL/min gives minutes."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 1, part a"},
{"id": "ws4-1b", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "amount-from-cp-vd", "skill": "vddose", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. What is the amount of the agent in the body when the concentration of drug in the plasma is 60 mg/L?", "units": "mg", "answer": 540, "tol": 5.4, "steps": [{"k": "setup", "t": "DB = Cp × VD", "why": "Concentration is amount divided by volume, Cp = {{frac:DB|VD}}, so multiplying the concentration by the volume gives the amount in the body."}, {"k": "algebra", "t": "DB = (60 mg/L)(9 L) = 540 mg", "why": "Litres cancel between mg/L and L, leaving milligrams, the amount of drug in the body at that concentration."}], "teach": [{"h": "Amount in the body", "list": ["Cp = {{frac:DB|VD}}, so DB = Cp × VD.", "mg/L × L = mg: the litres cancel and an amount is left."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 1, part b"},
{"id": "ws4-1c", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "rate-of-elimination", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. What is the rate of elimination (mg/hr) when the concentration of drug in the plasma is 50 mg/L?", "units": "mg/hr", "answer": 25, "tol": 0.25, "steps": [{"k": "setup", "t": "Rate of elimination = (Cl)(Cp)", "why": "The rate of elimination is clearance times concentration, a line on the equation sheet; it gives mg per hour."}, {"k": "algebra", "t": "Rate = (50 mg/L)(0.5 L/hr) = 25 mg/hr", "why": "Litres cancel between L/hr and mg/L, leaving mg per hour: an amount leaving the body per unit time."}], "teach": [{"h": "Rate of elimination", "list": ["Rate of elimination = Cl × Cp (on the equation sheet).", "L/hr × mg/L = mg/hr: an amount leaving per hour.", "Clearance stays constant; the rate falls as the concentration falls. Half the concentration, half the rate."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 1, part c"},
{"id": "ws4-1d", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "rate-of-elimination", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. What is the rate of elimination (mg/hr) when the concentration of drug in the plasma is 25 mg/L?", "units": "mg/hr", "answer": 12.5, "tol": 0.12, "steps": [{"k": "setup", "t": "Rate of elimination = (Cl)(Cp)", "why": "Clearance is constant at 0.5 L/hr, so the rate of elimination is again clearance times the plasma concentration."}, {"k": "algebra", "t": "Rate = (25 mg/L)(0.5 L/hr) = 12.5 mg/hr", "why": "Clearance is the same as in part c, so half the concentration gives half the rate: elimination rate is proportional to concentration."}], "teach": [{"h": "Rate of elimination", "list": ["Rate of elimination = Cl × Cp (on the equation sheet).", "L/hr × mg/L = mg/hr: an amount leaving per hour.", "Clearance stays constant; the rate falls as the concentration falls. Half the concentration, half the rate."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 1, part d"},
{"id": "ws4-1e", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "c-at-t-from-cl", "skill": "conctime", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. What is the expected plasma concentration 12 hours after a 700-mg intravenous bolus dose of the agent?", "units": "mg/L", "answer": 40, "tol": 0.4, "steps": [{"k": "setup", "t": "k = {{frac:Cl|VD}} = {{frac:0.5 L/hr|9 L}} = 0.0556 hr⁻¹", "why": "Cl = k × VD rearranged gives k = {{frac:Cl|VD}}; litres cancel and reciprocal hours are left, the unit a rate constant needs."}, {"k": "setup", "t": "C = {{frac:D0|VD}} e^(−kt)", "why": "After an IV bolus the concentration starts at {{frac:D0|VD}} and falls exponentially with the first-order rate constant."}, {"k": "algebra", "t": "C12 = {{frac:700 mg|9 L}} e^(−(0.0556)(12)) = (77.78)(0.513)", "why": "The exponent kt is (0.0556 hr⁻¹)(12 hr) = 0.667, a pure number because the hours cancel."}, {"k": "round", "t": "C12 = 40 mg/L", "why": "The product is 39.9 mg/L, reported as 40 mg/L; about half the initial 77.8 mg/L remains after 12 hours."}], "teach": [{"h": "Concentration at a time after an IV bolus", "list": ["C0 = {{frac:D0|VD}}, the concentration the moment the dose is in.", "C = C0 e^(−kt), first-order decline.", "k can come from clearance: k = {{frac:Cl|VD}}."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 1, part e"},
{"id": "ws4-1f", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "fe-from-urine", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. Urine was collected for 96 hours and 25 mg of unchanged the agent was recovered from the original 700-mg dose. What is the fraction of drug excreted in the urine?", "units": "(fraction)", "answer": 0.036, "tol": 0.00036, "steps": [{"k": "setup", "t": "fe = {{frac:Du∞|D0}}", "why": "The dose was given intravenously, so F = 1, and fe is the amount recovered unchanged divided by the dose."}, {"k": "algebra", "t": "fe = {{frac:25 mg|700 mg}} = 0.036", "why": "Milligrams cancel between the amount recovered and the dose, so fe is a pure fraction, here 3.6% of the dose."}], "teach": [{"h": "Fraction excreted unchanged", "list": ["fe = {{frac:Du∞|FD0}}: the share of the dose that leaves in urine as unchanged drug.", "After an IV dose F = 1, so fe = amount recovered unchanged ÷ dose.", "ke = fe × k: the excretion rate constant is the renal share of k.", "ClR = fe × ClT, and ClH = ClT − ClR = (1 − fe) ClT."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 2, part f"},
{"id": "ws4-1g", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "ke-from-fe", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. Urine was collected for 96 hours and 25 mg of unchanged the agent was recovered from the original 700-mg dose. What is the excretion rate constant of the agent?", "units": "hr⁻¹", "answer": 0.002, "tol": 2e-05, "steps": [{"k": "setup", "t": "ke = fe × k", "why": "fe = {{frac:ke|k}} rearranged gives ke = fe × k: the excretion rate constant is the renal share of the overall rate constant."}, {"k": "algebra", "t": "ke = (0.036)(0.0556 hr⁻¹) = 0.002 hr⁻¹", "why": "k is 0.0556 hr⁻¹, the rate constant from part e; fe has no units, so ke is also in reciprocal hours."}], "teach": [{"h": "Fraction excreted unchanged", "list": ["fe = {{frac:Du∞|FD0}}: the share of the dose that leaves in urine as unchanged drug.", "After an IV dose F = 1, so fe = amount recovered unchanged ÷ dose.", "ke = fe × k: the excretion rate constant is the renal share of k.", "ClR = fe × ClT, and ClH = ClT − ClR = (1 − fe) ClT."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 2, part g"},
{"id": "ws4-1h", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clr-from-fe", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. Urine was collected for 96 hours and 25 mg of unchanged the agent was recovered from the original 700-mg dose. What is the renal clearance of the agent?", "units": "L/hr", "answer": 0.018, "tol": 0.00018, "steps": [{"k": "setup", "t": "ClR = fe × ClT", "why": "Renal clearance is the fraction excreted unchanged times total clearance; fe has no units, so ClR keeps L/hr."}, {"k": "algebra", "t": "ClR = (0.036)(0.5 L/hr) = 0.018 L/hr", "why": "Renal clearance is fe times total clearance; fe has no units, so the renal clearance keeps the unit L/hr."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 2, part h", "note": "Her key prints the unit as \"L/hr⁻¹\"; the unit is L/hr."},
{"id": "ws4-1i", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clh-from-clt", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. Urine was collected for 96 hours and 25 mg of unchanged the agent was recovered from the original 700-mg dose. What is the metabolic (hepatic) clearance of the agent?", "units": "L/hr", "answer": 0.482, "tol": 0.0048, "steps": [{"k": "setup", "t": "ClH = ClT − ClR", "why": "Total clearance is renal plus hepatic, so subtracting the renal part from the total leaves the hepatic (metabolic) part."}, {"k": "algebra", "t": "ClH = (0.5 − 0.018) L/hr = 0.482 L/hr", "why": "Renal clearance is only 0.018 of the 0.5 L/hr total, so almost all of this drug is cleared by metabolism."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 2, part i"},
{"id": "ws4-1j", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "auc-from-cl", "skill": "clearance", "source": "slide", "stem": "The average clearance and volume of distribution of an antiepileptic agent in the adult patient population are 0.5 L/hr and 9 L, respectively. Urine was collected for 96 hours and 25 mg of unchanged the agent was recovered from the original 700-mg dose. What AUC would you expect from the 700-mg dose?", "units": "(mg/L)·hr", "answer": 1400, "tol": 14.0, "steps": [{"k": "setup", "t": "AUC = {{frac:D0|ClT}}", "why": "ClT = {{frac:FD0|AUC}} rearranged gives AUC = {{frac:FD0|ClT}}, and an IV dose has F = 1, so the whole 700 mg counts."}, {"k": "algebra", "t": "AUC = {{frac:700 mg|0.5 L/hr}} = 1400 (mg/L)·hr", "why": "Milligrams divided by litres per hour gives (mg/L)·hr, the unit of an area under a concentration–time curve."}], "teach": [{"h": "AUC from dose and clearance", "list": ["ClT = {{frac:FD0|AUC}}, so AUC = {{frac:FD0|ClT}}.", "mg ÷ (L/hr) = (mg/L) × hr, the unit of an area under a concentration–time curve."]}], "cite": "Clearance--26-Elimination-Practice-1-Solutions.pdf, page 2, part j"},
{"id": "ws4-2-1a", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "1. A single 250-mg oral dose of an antibiotic is given to a young man (age 32 years, creatinine clearance 122 mL/min, 78 kg). From the literature, the drug is known to have an apparent VD equal to 21% of body weight and an elimination half-life of 2 hours. The dose is normally 90% bioavailable. Urinary excretion of the unchanged drug is equal to 70% of the absorbed dose. What is the total body clearance for this drug? (Give it in L/hr.)", "units": "L/hr", "answer": 5.676, "tol": 0.057, "steps": [{"k": "unit", "t": "VD = (0.21)(78 kg) = 16.38 L", "why": "A volume given as a percentage of body weight is read as litres per kilogram: 21% of 78 kg is 0.21 × 78 = 16.38 L."}, {"k": "setup", "t": "ClT = VD × k, k = {{frac:0.693|2 hr}}", "why": "Total clearance is the elimination rate constant times the volume of distribution: reciprocal hours times litres gives L/hr."}, {"k": "algebra", "t": "ClT = (16.38 L)(0.3465 hr⁻¹) = 5.676 L/hr", "why": "Clearance comes from VD and k alone, so the 250 mg dose and the 90% bioavailability are not needed here."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Clearance--26-Elimination-Practice-2-Solutions.pdf, page 1, part 1a"},
{"id": "ws4-2-1a2", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "l-hr-to-ml-min", "skill": "clearance", "source": "slide", "stem": "1. A single 250-mg oral dose of an antibiotic is given to a young man (age 32 years, creatinine clearance 122 mL/min, 78 kg). From the literature, the drug is known to have an apparent VD equal to 21% of body weight and an elimination half-life of 2 hours. The dose is normally 90% bioavailable. Urinary excretion of the unchanged drug is equal to 70% of the absorbed dose. What is the total body clearance for this drug, in mL/min?", "units": "mL/min", "answer": 94.59, "tol": 0.95, "steps": [{"k": "unit", "t": "(5.676 L/hr)({{frac:1000 mL|1 L}})({{frac:1 hr|60 min}}) = 94.59 mL/min", "why": "Litres become millilitres (× 1000) and hours become minutes (÷ 60), so total clearance is in the same unit as CrCl."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Clearance--26-Elimination-Practice-2-Solutions.pdf, page 1, part 1a"},
{"id": "ws4-2-1b", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clr-from-fe", "skill": "clearance", "source": "slide", "stem": "1. A single 250-mg oral dose of an antibiotic is given to a young man (age 32 years, creatinine clearance 122 mL/min, 78 kg). From the literature, the drug is known to have an apparent VD equal to 21% of body weight and an elimination half-life of 2 hours. The dose is normally 90% bioavailable. Urinary excretion of the unchanged drug is equal to 70% of the absorbed dose. What is the renal clearance for this drug?", "units": "mL/min", "answer": 66.22, "tol": 0.66, "steps": [{"k": "setup", "t": "ClR = fe × ClT, fe = 0.7", "why": "Urinary excretion of unchanged drug is 70% of the absorbed dose, so fe = 0.7 and renal clearance is 0.7 of the total."}, {"k": "algebra", "t": "ClR = (0.7)(94.59 mL/min) = 66.22 mL/min", "why": "Using the unrounded total clearance, 94.594 mL/min, gives 66.22; the rounded 94.59 gives 66.21. Both are the same answer."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-2-Solutions.pdf, page 1, part 1b", "note": "0.7 × 94.59 gives 66.21; her key prints 66.22 because it carries the unrounded 94.594. Either is accepted."},
{"id": "ws4-2-1c", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "renalmech", "concept": "mechanism-from-clr", "skill": "apply", "source": "slide", "stem": "1. A single 250-mg oral dose of an antibiotic is given to a young man (age 32 years, creatinine clearance 122 mL/min, 78 kg). From the literature, the drug is known to have an apparent VD equal to 21% of body weight and an elimination half-life of 2 hours. The dose is normally 90% bioavailable. Urinary excretion of the unchanged drug is equal to 70% of the absorbed dose. What is the probable mechanism for renal clearance of this drug?", "options": [{"t": "Filtered at the glomerulus and partially reabsorbed", "correct": true, "why": "Renal clearance, 66.22 mL/min, is less than the creatinine clearance, 122 mL/min, the estimate of GFR. Less than filtration means some filtered drug returns to the blood."}, {"t": "Filtered and actively secreted", "why": "Active secretion adds drug to the urine on top of filtration, so renal clearance would be above GFR. Here it is below."}, {"t": "Filtered only, nothing else", "why": "Filtration alone gives a renal clearance equal to the GFR, about 122 mL/min for this patient, not the 66 mL/min found here."}, {"t": "Cleared mainly by the liver", "why": "fe is 0.7, so most of the absorbed dose leaves through the kidney; the question is how the kidney handles it."}], "teach": [{"h": "Reading the renal mechanism", "list": ["Compare renal clearance with the GFR, estimated by CrCl or taken as about 120 mL/min.", "Equal to GFR: filtration only.", "Greater than GFR: filtration plus active secretion.", "Less than GFR: filtration with partial reabsorption."]}], "cite": "Clearance--26-Elimination-Practice-2-Solutions.pdf, page 1, part 1c"},
{"id": "ws4-2-2", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "crclcalc", "concept": "cockcroft-gault", "skill": "crcl", "source": "slide", "stem": "2. Estimate the creatinine clearance of a 37-year-old female who weighs 143 lb, serum creatinine of 0.6 mg/dL, and stands 5’6” tall.", "units": "mL/min", "answer": 120.2, "tol": 1.2, "steps": [{"k": "unit", "t": "5 ft 6 in: 6 inches over 5 ft", "why": "A height of 5 ft 6 in is already in feet and inches, so the inches over 5 ft, 6, are read straight off it."}, {"k": "algebra", "t": "IBW = 45.5 + 2.3(6) = 59.3 kg", "why": "The female form starts at 45.5 kg. The 143 lb total body weight is not used, because her keys use ideal body weight."}, {"k": "setup", "t": "CrCl = 0.85 × {{frac:(140 − 37)(59.3)|(72)(0.6)}}", "why": "This is the Cockcroft-Gault equation; the patient is female, so the result is multiplied by 0.85."}, {"k": "round", "t": "CrCl = 120.2 mL/min", "why": "The result is reported to one decimal place in mL/min, the unit creatinine clearance is always given in."}], "teach": [{"h": "The method, in order", "list": ["Height in centimetres: divide by 2.54 to get inches, then count the inches over 60 (5 ft).", "Ideal body weight (IBW): male 50 + 2.3 × (inches over 5 ft); female 45.5 + 2.3 × (inches over 5 ft).", "CrCl = {{frac:(140 − age)(IBW)|72 × SCr}}, then × 0.85 if the patient is female.", "Her keys use IBW, not the weight given in the stem.", "Report CrCl in mL/min. It estimates the glomerular filtration rate (GFR), about 120 mL/min in a healthy adult."]}], "cite": "Clearance--26-Elimination-Practice-2-Solutions.pdf, page 1, problem 2"},
{"id": "ws4-3a", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "crclcalc", "concept": "cockcroft-gault", "skill": "crcl", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. a. Estimate KL’s creatinine clearance.", "units": "mL/min", "answer": 121.17, "tol": 1.2, "steps": [{"k": "unit", "t": "178 cm ÷ 2.54 = 70.08 in, taken as 10 in over 5 ft", "why": "The inches over 5 ft are rounded to a whole number before the IBW is computed, the way her keys do it."}, {"k": "algebra", "t": "IBW = 50 + 2.3(10) = 73 kg", "why": "The male form of the ideal body weight equation starts at 50 kg and adds 2.3 kg for each inch over 5 ft."}, {"k": "setup", "t": "CrCl = {{frac:(140 − 42)(73 kg)|(72)(0.82)}} = 121.17 mL/min", "why": "This is the Cockcroft-Gault equation; the patient is male, so the 0.85 factor for a female patient is not applied."}], "teach": [{"h": "The method, in order", "list": ["Height in centimetres: divide by 2.54 to get inches, then count the inches over 60 (5 ft).", "Ideal body weight (IBW): male 50 + 2.3 × (inches over 5 ft); female 45.5 + 2.3 × (inches over 5 ft).", "CrCl = {{frac:(140 − age)(IBW)|72 × SCr}}, then × 0.85 if the patient is female.", "Her keys use IBW, not the weight given in the stem.", "Report CrCl in mL/min. It estimates the glomerular filtration rate (GFR), about 120 mL/min in a healthy adult."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 1, part a", "note": "With 10.08 inches instead of 10, IBW is 73.18 kg and CrCl 121.47 mL/min; both are accepted."},
{"id": "ws4-3b", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. b. Estimate the total body clearance (mL/min) of cefprozil in KL.", "units": "mL/min", "answer": 149, "tol": 1.5, "steps": [{"k": "setup", "t": "ClT = (0.23 L/kg)(73 kg)({{frac:0.693|1.3 hr}}) = 8.95 L/hr", "why": "KL has normal renal function here, so the 1.3 hr half-life is used, and VD in L/kg is multiplied by 73 kg."}, {"k": "unit", "t": "(8.95 L/hr)({{frac:1000 mL|L}})({{frac:1 hr|60 min}}) = 149 mL/min", "why": "Converting to mL/min puts total clearance in the same unit as creatinine clearance, so the two can be compared."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 1, part b"},
{"id": "ws4-3c", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clr-from-fe", "skill": "clearance", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. c. Estimate the renal clearance (mL/min) of cefprozil in KL.", "units": "mL/min", "answer": 89.5, "tol": 0.9, "steps": [{"k": "setup", "t": "ClR = fe × ClT = (0.6)(149 mL/min)", "why": "About 60% of the drug is excreted unchanged in urine, so fe = 0.6 and renal clearance is 0.6 of total clearance."}, {"k": "round", "t": "ClR = 89.5 mL/min", "why": "The total clearance unrounded is 149.17 mL/min, and 0.6 of it is 89.50 mL/min, reported to one decimal."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 1, part c", "note": "(0.6)(149) gives 89.4; her key prints 89.5 from the unrounded 149.17. Either is accepted."},
{"id": "ws4-3d", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clh-from-clt", "skill": "clearance", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. d. Estimate the hepatic clearance (mL/min) of cefprozil in KL.", "units": "mL/min", "answer": 59.5, "tol": 0.59, "steps": [{"k": "setup", "t": "ClH = ClT − ClR = (149 − 89.5) mL/min = 59.5 mL/min", "why": "Total clearance is renal plus hepatic, so whatever is not cleared by the kidney is cleared by the liver."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 1, part d"},
{"id": "ws4-3e", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "crclcalc", "concept": "cockcroft-gault", "skill": "crcl", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. e. If KL developed some severe complications and his serum creatinine sky-rocketed to 2.8 mg/dL, revise your estimate of KL’s creatinine clearance.", "units": "mL/min", "answer": 35.49, "tol": 0.35, "steps": [{"k": "setup", "t": "CrCl = {{frac:(140 − 42)(73 kg)|(72)(2.8)}} = 35.49 mL/min", "why": "Only the serum creatinine changes; it sits in the denominator, so a higher SCr gives a lower creatinine clearance."}], "teach": [{"h": "The method, in order", "list": ["Height in centimetres: divide by 2.54 to get inches, then count the inches over 60 (5 ft).", "Ideal body weight (IBW): male 50 + 2.3 × (inches over 5 ft); female 45.5 + 2.3 × (inches over 5 ft).", "CrCl = {{frac:(140 − age)(IBW)|72 × SCr}}, then × 0.85 if the patient is female.", "Her keys use IBW, not the weight given in the stem.", "Report CrCl in mL/min. It estimates the glomerular filtration rate (GFR), about 120 mL/min in a healthy adult."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 1, part e"},
{"id": "ws4-3f", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. f. Provide a new estimate of the total body clearance (mL/min) of cefprozil in KL assuming his volume of distribution is unchanged.", "units": "mL/min", "answer": 37.29, "tol": 0.37, "steps": [{"k": "setup", "t": "35.49 mL/min lies between 30 and 120, so t½ = 5.2 hr", "why": "The stem gives a half-life for each CrCl band; 35.49 mL/min lies between 30 and 120, so the 5.2 hr value applies."}, {"k": "algebra", "t": "ClT = (0.23 L/kg)(73 kg)({{frac:0.693|5.2 hr}}) = 2.24 L/hr", "why": "The volume of distribution is unchanged and the half-life is now 5.2 hr, so k and the clearance are both smaller."}, {"k": "unit", "t": "(2.24 L/hr)({{frac:1000 mL|L}})({{frac:1 hr|60 min}}) = 37.29 mL/min", "why": "The unrounded 2.2376 L/hr converts to 37.29 mL/min; the rounded 2.24 L/hr would give 37.33."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 2, part f", "note": "The rounded 2.24 L/hr gives 37.33 mL/min; her key prints 37.29 from 2.2376. Either is accepted."},
{"id": "ws4-3g", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clr-from-fe", "skill": "clearance", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. g. Provide a new estimate of the renal clearance (mL/min) of cefprozil in KL.", "units": "mL/min", "answer": 22.38, "tol": 0.22, "steps": [{"k": "setup", "t": "ClR = (0.6)(37.29 mL/min) = 22.38 mL/min", "why": "The fraction excreted unchanged is still 0.6, so renal clearance is 0.6 of the new, lower total clearance."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 2, part g"},
{"id": "ws4-3h", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "clh-from-clt", "skill": "clearance", "source": "slide", "stem": "Cefprozil, 500 mg oral every 12 hours for 10 days, has been prescribed for patient, KL. KL is a 42 year old male, who is 178 cm tall and weighs 73 kg and has a serum creatinine of 0.82 mg/dL. Cefprozil is well absorbed with a bioavailability of about 95%. The half-life of elimination in adults with normal hepatic and renal function is about 1.3 hours, 5.2 hours in adults with renal impairment (120 > CrCl > 30mL/min), and 5.9 hours in patients with renal failure (CrCl< 30mL/min),. The apparent volume of distribution is 0.23 L/kg. About 60% of the drug is excreted in the urine as unchanged drug. According to the manufacturer's labeling for adults, no dosage adjustment is necessary if the CrCl ≥30 mL/minute and the dose should be reduced by 50% if CrCl <30 mL/minute. h. Provide a new estimate of the hepatic clearance (mL/min) of cefprozil in KL.", "units": "mL/min", "answer": 14.91, "tol": 0.15, "steps": [{"k": "setup", "t": "ClH = (37.29 − 22.38) mL/min = 14.91 mL/min", "why": "Total clearance minus renal clearance leaves hepatic clearance, because the two routes add up to the total."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Clearance--26-Elimination-Practice-3-Solutions-281-29.pdf, page 2, part h"},
{"id": "ws4-4-1a", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "renalmech", "concept": "mechanism-from-clr", "skill": "apply", "source": "slide", "stem": "1. A new antibiotic is excreted by the kidney. The apparent volume of distribution is 25L in the normal adult. The clearance of this drug is 300 mL/min. a. What is the probable mechanism of renal excretion of this drug?", "options": [{"t": "Active secretion", "correct": true, "why": "Clearance, 300 mL/min, is well above GFR (about 120 mL/min). Only secretion can clear more plasma than is filtered."}, {"t": "Filtration only", "why": "Filtration alone clears plasma at the GFR, about 120 mL/min; a renal clearance of 300 mL/min is more than filtration can do."}, {"t": "Filtration with partial reabsorption", "why": "Reabsorption returns filtered drug to the blood, which puts renal clearance below the GFR; here it is above."}, {"t": "Hepatic metabolism", "why": "The stem says the drug is excreted by the kidney, so the clearance given is renal and the question is which renal process."}], "teach": [{"h": "Reading the renal mechanism", "list": ["Compare renal clearance with the GFR, estimated by CrCl or taken as about 120 mL/min.", "Equal to GFR: filtration only.", "Greater than GFR: filtration plus active secretion.", "Less than GFR: filtration with partial reabsorption."]}], "cite": "Clearance--26-Elimination-Practice-4-Solutions.pdf, page 1, part 1a"},
{"id": "ws4-4-1b", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "thalf-from-cl-vd", "skill": "krate", "source": "slide", "stem": "1. A new antibiotic is excreted by the kidney. The apparent volume of distribution is 25L in the normal adult. The clearance of this drug is 300 mL/min. b. What is the usual t½ for this drug?", "units": "min", "answer": 58, "tol": 0.58, "steps": [{"k": "unit", "t": "VD = 25 L = 25,000 mL", "why": "Clearance is given in mL/min, so the volume is converted to mL as well; then mL cancels and the half-life comes out in minutes."}, {"k": "algebra", "t": "t½ = {{frac:(0.693)(25,000 mL)|300 mL/min}} = 58 min", "why": "Millilitres cancel between the volume and the clearance, so the half-life comes out in minutes."}], "teach": [{"h": "Half-life from clearance and volume", "list": ["Cl = k × VD (one of the equations she expects without the sheet).", "k = {{frac:0.693|t½}}, so t½ = {{frac:0.693 VD|Cl}}.", "A larger volume or a smaller clearance gives a longer half-life.", "Keep the units matched: L with L/hr gives hours; mL with mL/min gives minutes."]}], "cite": "Clearance--26-Elimination-Practice-4-Solutions.pdf, page 1, part 1b"},
{"id": "ws4-4-1c", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "clcalc", "concept": "thalf-from-cl-vd", "skill": "krate", "source": "slide", "stem": "1. A new antibiotic is excreted by the kidney. The apparent volume of distribution is 25L in the normal adult. The clearance of this drug is 300 mL/min. c. What would be the new t½ for this drug in an adult with partial renal failure whose clearance of the antibiotic was 125 mL/min?", "units": "min", "answer": 139, "tol": 1.4, "steps": [{"k": "algebra", "t": "t½ = {{frac:(0.693)(25,000 mL)|125 mL/min}} = 139 min", "why": "The volume is the same and the clearance is lower, so the half-life is longer: 125 mL/min gives 139 minutes."}], "teach": [{"h": "Half-life from clearance and volume", "list": ["Cl = k × VD (one of the equations she expects without the sheet).", "k = {{frac:0.693|t½}}, so t½ = {{frac:0.693 VD|Cl}}.", "A larger volume or a smaller clearance gives a longer half-life.", "Keep the units matched: L with L/hr gives hours; mL with mL/min gives minutes."]}], "cite": "Clearance--26-Elimination-Practice-4-Solutions.pdf, page 1, part 1c"},
{"id": "ws4-4-2", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 4, "lecture": "L05", "topic": "clearance", "sub": "crclcalc", "concept": "cockcroft-gault", "skill": "crcl", "source": "slide", "stem": "2. Estimate the CrCl of a 42-year-old female who weighs 82kg, SCr =0.9 mg/dL, and 170 cm tall.", "units": "mL/min", "answer": 79.19, "tol": 0.79, "steps": [{"k": "unit", "t": "170 cm ÷ 2.54 = 66.93 in, taken as 7 in over 5 ft", "why": "The inches over 5 ft are rounded to a whole number before the IBW is computed, the way her keys do it."}, {"k": "algebra", "t": "IBW = 45.5 + 2.3(7) = 61.6 kg", "why": "The female form starts at 45.5 kg. The 82 kg total body weight is not used, because her keys use ideal body weight."}, {"k": "setup", "t": "CrCl = 0.85 × {{frac:(140 − 42)(61.6)|(72)(0.9)}} = 79.19 mL/min", "why": "This is the Cockcroft-Gault equation; the patient is female, so the result is multiplied by 0.85."}], "teach": [{"h": "The method, in order", "list": ["Height in centimetres: divide by 2.54 to get inches, then count the inches over 60 (5 ft).", "Ideal body weight (IBW): male 50 + 2.3 × (inches over 5 ft); female 45.5 + 2.3 × (inches over 5 ft).", "CrCl = {{frac:(140 − age)(IBW)|72 × SCr}}, then × 0.85 if the patient is female.", "Her keys use IBW, not the weight given in the stem.", "Report CrCl in mL/min. It estimates the glomerular filtration rate (GFR), about 120 mL/min in a healthy adult."]}], "cite": "Clearance--26-Elimination-Practice-4-Solutions.pdf, page 1, problem 2", "note": "With 6.93 inches instead of 7, IBW is 61.44 kg and CrCl 78.98 mL/min; both are accepted."},
{"id": "ws5-1-1t", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 1. Total body clearance (and renal and metabolic clearance). What is the total body clearance?", "units": "L/hr", "answer": 32.34, "tol": 0.32, "steps": [{"k": "setup", "t": "ClT = VD × k = (140 L)({{frac:0.693|3 hr}}) = 32.34 L/hr", "why": "Clearance is k times the volume of distribution, with k from the 3 hr half-life measured after the IV dose."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 1, part 1"},
{"id": "ws5-1-1r", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clr-from-fe", "skill": "clearance", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 1. Total body clearance, renal clearance and metabolic clearance. What is the renal clearance?", "units": "L/hr", "answer": 21.02, "tol": 0.21, "steps": [{"k": "setup", "t": "ClR = fe × ClT = (32.34 L/hr)(0.65) = 21.02 L/hr", "why": "The stem says 65% is excreted in the urine unchanged, so fe = 0.65 and the renal clearance is 0.65 of the total."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 1, part 1"},
{"id": "ws5-1-1m", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clh-from-clt", "skill": "clearance", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 1. Total body clearance, renal clearance and metabolic clearance. What is the metabolic clearance?", "units": "L/hr", "answer": 11.32, "tol": 0.11, "steps": [{"k": "setup", "t": "ClH = (32.34 L/hr)(0.35) = 11.32 L/hr", "why": "The stem says 35% of the dose is metabolized, so the metabolic (hepatic) clearance is 0.35 of the total clearance."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 1, part 1"},
{"id": "ws5-1-2t", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "tmax-oral", "skill": "oral", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 2. Time to peak following the oral administration of a 250 mg dose.", "units": "hr", "answer": 0.97, "tol": 0.0097, "steps": [{"k": "setup", "t": "k = {{frac:0.693|3 hr}} = 0.231 hr⁻¹", "why": "The elimination rate constant is 0.693 divided by the 3 hr half-life; it is needed because tmax depends on k."}, {"k": "algebra", "t": "tmax = {{frac:ln(2.8/0.231)|(2.8 − 0.231) hr⁻¹}} = 0.97 hr", "why": "{{frac:ka|k}} is a ratio of two rate constants, a pure number, and dividing its log by (ka − k) in hr⁻¹ gives hours."}], "teach": [{"h": "Time to peak after one oral dose", "list": ["tmax = {{frac:ln(ka/k)|ka − k}}.", "k = {{frac:0.693|t½}}; ka = {{frac:0.693|t½}} absorption.", "The dose and F do not appear: the time to peak depends only on ka and k."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 1, part 2"},
{"id": "ws5-1-2c", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "cmax-oral", "skill": "oral", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 2. Maximum plasma concentration following the oral administration of a 250 mg dose.", "units": "mg/L", "answer": 1.22, "tol": 0.012, "steps": [{"k": "setup", "t": "Cmax = {{frac:F ka D0|VD(ka − k)}} (e^(−k tmax) − e^(−ka tmax))", "why": "Cmax is the single-dose oral equation evaluated at tmax; the dose, F and both rate constants are needed."}, {"k": "algebra", "t": "Cmax = {{frac:(0.8554)(250 mg)(2.8 hr⁻¹)|140 L (2.8 − 0.231) hr⁻¹}} (e^(−(0.97)(0.231)) − e^(−(0.97)(2.8)))", "why": "Reciprocal hours cancel between ka and (ka − k), and mg ÷ L leaves mg/L, so the peak comes out as a concentration."}, {"k": "round", "t": "Cmax = 1.22 mg/L", "why": "The peak is reported to two decimal places in mg/L, which is the same as mcg/mL for comparison with the range."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 1, part 2"},
{"id": "ws5-1-2d", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "cmax-dose-proportional", "skill": "oral", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 2. Maximum plasma concentration following the oral administration of a 500 mg dose.", "units": "mg/L", "answer": 2.44, "tol": 0.024, "steps": [{"k": "setup", "t": "Same equation, D0 = 500 mg; tmax is still 0.97 hr", "why": "tmax depends only on ka and k, so the 500 mg dose peaks at the same 0.97 hr as the 250 mg dose."}, {"k": "algebra", "t": "Cmax = {{frac:(0.8554)(500 mg)(2.8 hr⁻¹)|140 L (2.8 − 0.231) hr⁻¹}} (e^(−(0.97)(0.231)) − e^(−(0.97)(2.8))) = 2.44 mg/L", "why": "With first-order kinetics the peak is proportional to the dose, so twice the dose gives twice the peak, 2.44 mg/L."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 1, part 2"},
{"id": "ws5-1-3", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "cmax-vs-range", "skill": "apply", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 3. Whether the 250 mg tablet will provide a maximum plasma concentration sufficient to control the arrhythmia.", "options": [{"t": "No: its peak, 1.22 mg/L, is below the 4 mcg/mL lower limit", "correct": true, "why": "1 mg/L and 1 mcg/mL are the same concentration, so the 1.22 mg/L peak is 1.22 mcg/mL, which never reaches the 4 to 8 mcg/mL range."}, {"t": "Yes: 1.22 mg/L is above 1 mcg/mL", "why": "This compares the peak with the wrong number. The therapeutic range starts at 4 mcg/mL, and 1.22 is below it."}, {"t": "Yes, after unit conversion 1.22 mg/L is 1220 mcg/mL", "why": "Converting 1 mg/L gives 1000 mcg in 1000 mL, which is 1 mcg/mL. Multiplying by 1000 forgets that the volume also changed."}, {"t": "It cannot be judged without the AUC", "why": "The question asks about the peak, and Cmax is compared with the therapeutic range directly; no AUC is needed."}], "teach": [{"h": "Comparing a peak with a range", "list": ["mg/L and mcg/mL are the same size: 1 mg/L = 1 mcg/mL.", "A peak below the lower limit of the range never reaches an effective level."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 3"},
{"id": "ws5-1-4", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "tablets-to-range", "skill": "apply", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 4. If the 250 mg tablet is insufficient to control the arrhythmia, how many tablets (250 mg strength) will be required to control the arrhythmia?", "options": [{"t": "4 to 6 tablets", "correct": true, "why": "Each tablet adds 1.22 mg/L to the peak. {{frac:4|1.22}} = 3.28, so 4 tablets reach the minimum; {{frac:8|1.22}} = 6.56, so 6 tablets stay under the maximum."}, {"t": "3 to 6 tablets", "why": "Each tablet adds 1.22 mg/L, so 3 tablets give 3.66 mg/L, still below 4 mcg/mL. The minimum needs one more tablet."}, {"t": "4 to 7 tablets", "why": "Each tablet adds 1.22 mg/L, so 7 tablets give 8.54 mg/L, above the 8 mcg/mL upper limit of the therapeutic range."}, {"t": "2 tablets", "why": "Each tablet adds 1.22 mg/L to the peak, so 2 tablets give 2.44 mg/L, still below the 4 mcg/mL lower limit."}], "teach": [{"h": "Scaling a peak to a range", "list": ["Cmax is proportional to the dose, so each tablet adds the same peak.", "Tablets for the minimum: round up. Tablets for the maximum: round down."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 4", "note": "Her key writes 3.27 and 6.55 ({{frac:4|1.22}} and {{frac:8|1.22}} cut off at two decimals); the tablet counts are the same."},
{"id": "ws5-1-5t", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 5. In a 70 kg patient with renal impairment, the elimination half-life is reported to be 14 hours. Assuming no change in apparent volume of distribution, absorption rate constant, and fraction absorbed systemically, determine the total body, renal, and metabolic clearances following the administration of a 250 tablet to this subject. What is the total body clearance?", "units": "L/hr", "answer": 6.93, "tol": 0.069, "steps": [{"k": "setup", "t": "ClT = (140 L)({{frac:0.693|14 hr}}) = 6.93 L/hr", "why": "The volume is unchanged and the half-life is longer, so k is smaller and the clearance (k × VD) is lower."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 5"},
{"id": "ws5-1-5r", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clr-from-fe", "skill": "clearance", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 5. In a 70 kg patient with renal impairment, the elimination half-life is reported to be 14 hours. Assuming no change in apparent volume of distribution, absorption rate constant, and fraction absorbed systemically, determine the total body, renal, and metabolic clearances following the administration of a 250 tablet to this subject. What is the renal clearance?", "units": "L/hr", "answer": 4.5, "tol": 0.045, "steps": [{"k": "setup", "t": "ClR = (6.93 L/hr)(0.65) = 4.5 L/hr", "why": "The renal and metabolic shares are assumed unchanged at 65% and 35%, so ClR is 0.65 of the new, lower total clearance."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 5"},
{"id": "ws5-1-5m", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clh-from-clt", "skill": "clearance", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 5. In a 70 kg patient with renal impairment, the elimination half-life is reported to be 14 hours. Assuming no change in apparent volume of distribution, absorption rate constant, and fraction absorbed systemically, determine the total body, renal, and metabolic clearances following the administration of a 250 tablet to this subject. What is the metabolic clearance?", "units": "L/hr", "answer": 2.43, "tol": 0.024, "steps": [{"k": "setup", "t": "ClH = (6.93 L/hr)(0.35) = 2.43 L/hr", "why": "The 35% metabolized share is unchanged by renal impairment in this problem, so ClH stays 0.35 of the new, lower total."}], "teach": [{"h": "Splitting total clearance", "list": ["ClR = fe × ClT (renal: the share excreted unchanged).", "ClH = ClT − ClR = (1 − fe) × ClT (hepatic or metabolic: the rest).", "ClT = ClR + ClH."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 5"},
{"id": "ws5-1-6t", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "tmax-oral", "skill": "oral", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 6. Determine tmax and Cmax for this patient with renal impairment (elimination half-life 14 hours) following a 250 mg oral dose. What is tmax?", "units": "hr", "answer": 1.467, "tol": 0.015, "steps": [{"k": "setup", "t": "k = {{frac:0.693|14 hr}} = 0.0495 hr⁻¹", "why": "The 14 hr half-life gives a smaller elimination rate constant, 0.0495 hr⁻¹, in place of the 0.231 hr⁻¹ for a healthy subject."}, {"k": "algebra", "t": "tmax = {{frac:ln(2.8/0.0495)|(2.8 − 0.0495) hr⁻¹}} = 1.467 hr", "why": "A smaller elimination rate constant moves the peak later, because absorption outpaces elimination for longer."}], "teach": [{"h": "Time to peak after one oral dose", "list": ["tmax = {{frac:ln(ka/k)|ka − k}}.", "k = {{frac:0.693|t½}}; ka = {{frac:0.693|t½}} absorption.", "The dose and F do not appear: the time to peak depends only on ka and k."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 6"},
{"id": "ws5-1-6c", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "cmax-oral", "skill": "oral", "source": "slide", "stem": "Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: 6. Determine tmax and Cmax for this patient with renal impairment (elimination half-life 14 hours) following a 250 mg oral dose. What is Cmax?", "units": "mg/L", "answer": 1.42, "tol": 0.014, "steps": [{"k": "algebra", "t": "Cmax = {{frac:(0.8554)(250 mg)(2.8 hr⁻¹)|140 L (2.8 − 0.0495) hr⁻¹}} (e^(−(1.5)(0.0495)) − e^(−(1.5)(2.8))) = 1.42 mg/L", "why": "With the smaller k the peak is higher than the 1.22 mg/L in a healthy subject, because less drug is eliminated while absorption goes on."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Singler-Oral-1---Solutions.pdf, page 2, part 6", "note": "Her key computes tmax = 1.467 hr and uses t = 1.5 hr here; Cmax is 1.42 mg/L either way."},
{"id": "ws5-2-1", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "vd-from-oral-coef", "skill": "vddose", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 1. Volume of distribution", "units": "L", "answer": 171.43, "tol": 1.7, "steps": [{"k": "unit", "t": "70 ng/mL × {{frac:1000 mL|L}} × {{frac:1 mg|10⁶ ng}} = 0.07 mg/L", "why": "The coefficient is converted from ng/mL to mg/L so that mg ÷ (mg/L) leaves litres for the volume of distribution."}, {"k": "setup", "t": "VD = {{frac:F ka D0|A(ka − k)}}, ka = 0.3, k = 0.1", "why": "In the fitted equation the larger exponent belongs to absorption and the smaller to elimination: ka = 0.3, k = 0.1 hr⁻¹."}, {"k": "algebra", "t": "VD = {{frac:(0.8)(10 mg)(0.3 hr⁻¹)|(0.07 mg/L)(0.3 − 0.1) hr⁻¹}} = 171.43 L", "why": "Milligrams divided by milligrams per litre leaves litres, the unit of a volume of distribution."}], "teach": [{"h": "Reading the fitted oral equation", "list": ["The fitted form is Cp = A(e^(−kt) − e^(−ka t)).", "The smaller exponent is k; the larger is ka.", "A = {{frac:F ka D0|VD(ka − k)}}, so VD = {{frac:F ka D0|A(ka − k)}}.", "Put A in mg/L before solving for a volume in litres."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 1, part 1"},
{"id": "ws5-2-2", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 2. Total body clearance", "units": "L/hr", "answer": 17.143, "tol": 0.17, "steps": [{"k": "setup", "t": "ClT = VD × k = (171.43 L)(0.1 hr⁻¹) = 17.143 L/hr", "why": "The elimination rate constant is the smaller exponent, 0.1 hr⁻¹; litres times reciprocal hours gives L/hr."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 1, part 2"},
{"id": "ws5-2-3", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "thalf-from-k", "skill": "krate", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 3. Half-life of elimination", "units": "hr", "answer": 6.93, "tol": 0.069, "steps": [{"k": "setup", "t": "t½ = {{frac:0.693|0.1 hr⁻¹}} = 6.93 hr", "why": "The first-order half-life is 0.693 divided by the elimination rate constant; reciprocal hours in the denominator give hours."}], "teach": [{"h": "Half-lives from rate constants", "list": ["t½ = {{frac:0.693|k}} for elimination; t½a = {{frac:0.693|ka}} for absorption.", "In a fitted oral equation the smaller exponent is k and the larger is ka.", "A rate constant in hr⁻¹ gives a half-life in hours."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 1, part 3"},
{"id": "ws5-2-4", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "extravasc", "concept": "thalf-abs", "skill": "krate", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 4. Half-life of absorption", "units": "hr", "answer": 2.31, "tol": 0.023, "steps": [{"k": "setup", "t": "t½a = {{frac:0.693|0.3 hr⁻¹}} = 2.31 hr", "why": "The absorption half-life is 0.693 divided by the absorption rate constant, the same first-order relation applied to ka."}], "teach": [{"h": "Half-lives from rate constants", "list": ["t½ = {{frac:0.693|k}} for elimination; t½a = {{frac:0.693|ka}} for absorption.", "In a fitted oral equation the smaller exponent is k and the larger is ka.", "A rate constant in hr⁻¹ gives a half-life in hours."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 1, part 4"},
{"id": "ws5-2-5", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "cmax-oral", "skill": "oral", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 5. Maximum plasma concentration", "units": "ng/mL", "answer": 26.94, "tol": 0.27, "steps": [{"k": "setup", "t": "tmax = {{frac:ln(0.3/0.1)|(0.3 − 0.1) hr⁻¹}} = 5.49 hr", "why": "The peak occurs at tmax, which depends only on ka and k, so it is found first and then put into the equation."}, {"k": "algebra", "t": "Cmax = 70 ng/mL (e^(−(0.1)(5.49)) − e^(−(0.3)(5.49))) = 26.94 ng/mL", "why": "Putting tmax into the fitted equation gives the peak concentration, in the equation's own unit, ng/mL."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 1, part 5"},
{"id": "ws5-2-6", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "changes", "concept": "cmax-dose-proportional", "skill": "oral", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 6. Maximum plasma concentration if the dose were increased to 20 mg", "units": "ng/mL", "answer": 53.88, "tol": 0.54, "steps": [{"k": "setup", "t": "Cmax = {{frac:(0.8)(20 mg)(0.3 hr⁻¹)|(171.43 L)(0.3 − 0.1) hr⁻¹}} (e^(−(0.1)(5.49)) − e^(−(0.3)(5.49))) = 0.05388 mg/L", "why": "tmax depends only on ka and k, so doubling the dose leaves it at 5.49 hr while the coefficient doubles."}, {"k": "unit", "t": "0.05388 mg/L × {{frac:1 L|1000 mL}} × {{frac:10⁶ ng|1 mg}} = 53.88 ng/mL", "why": "The result equals 2 × 26.94 ng/mL: with first-order kinetics the peak is proportional to the dose, and tmax does not move."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 2, part 6", "note": "Her key prints 0.0588 mg/L on the first line and 0.05388 on the next; 0.05388 is the value."},
{"id": "ws5-2-7", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "changes", "concept": "thalf-from-cl-vd", "skill": "krate", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 7. Half-life of elimination if the clearance were reduced to 8.57 L/hr, assuming no change in apparent volume of distribution", "units": "hr", "answer": 13.86, "tol": 0.14, "steps": [{"k": "setup", "t": "t½ = {{frac:0.693(171.43 L)|8.57 L/hr}} = 13.86 hr", "why": "With the volume unchanged, half the clearance gives twice the half-life: 6.93 hr becomes 13.86 hr."}], "teach": [{"h": "Half-life from clearance and volume", "list": ["Cl = k × VD (one of the equations she expects without the sheet).", "k = {{frac:0.693|t½}}, so t½ = {{frac:0.693 VD|Cl}}.", "A larger volume or a smaller clearance gives a longer half-life.", "Keep the units matched: L with L/hr gives hours; mL with mL/min gives minutes."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 2, part 7"},
{"id": "ws5-2-8", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "changes", "concept": "cmax-oral", "skill": "oral", "source": "slide", "stem": "A 10-mg single dose of a drug is given orally to a patient. The drug is about 80% absorbed and the equation that fits the observed data is Cp = 70 ng/mL (e^(−0.1t) − e^(−0.3t)). [Rate constants are in hr⁻¹]. Determine the following: 8. Maximum plasma concentration for a 10 mg dose if the clearance were reduced to 8.57 L/hr, assuming no change in apparent volume of distribution", "units": "ng/mL", "answer": 32.61, "tol": 0.33, "steps": [{"k": "setup", "t": "k = {{frac:8.57 L/hr|171.43 L}} = 0.05 hr⁻¹", "why": "Clearance equals k times the volume of distribution, so dividing clearance by the volume gives the rate constant in reciprocal hours."}, {"k": "algebra", "t": "tmax = {{frac:ln(0.3/0.05)|(0.3 − 0.05) hr⁻¹}} = 7.17 hr", "why": "A smaller elimination rate constant moves the peak later, because absorption outpaces elimination for longer."}, {"k": "algebra", "t": "Cmax = {{frac:(0.8)(10 mg)(0.3 hr⁻¹)|(171.43 L)(0.3 − 0.05) hr⁻¹}} (e^(−(0.05)(7.17)) − e^(−(0.3)(7.17))) = 0.03261 mg/L", "why": "The coefficient contains (ka − k), so when k changes the whole oral equation is used rather than the old fitted coefficient."}, {"k": "unit", "t": "0.03261 mg/L = 32.61 ng/mL", "why": "The answer is higher than 26.94 ng/mL: with slower elimination, more drug builds up before the peak, so the peak is higher and later."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Single-Oral-2---Solutions.pdf, page 2, part 8"},
{"id": "ws5-3-1", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "clt-from-vd-k", "skill": "clearance", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 1. Total body clearance", "units": "L/hr", "answer": 1.6632, "tol": 0.017, "steps": [{"k": "setup", "t": "ClT = (24 L)({{frac:0.693|10 hr}}) = 1.6632 L/hr", "why": "Total clearance is the elimination rate constant times the volume of distribution: reciprocal hours times litres gives L/hr."}], "teach": [{"h": "Total clearance from volume and half-life", "list": ["k = {{frac:0.693|t½}}.", "ClT = VD × k. When VD is given per kilogram or as a percentage of body weight, multiply by the weight first.", "L/hr to mL/min: × 1000 mL/L, ÷ 60 min/hr."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 1"},
{"id": "ws5-3-2", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "auc-from-cl", "skill": "clearance", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 2. AUC", "units": "(mg/L)·hr", "answer": 481, "tol": 4.8, "steps": [{"k": "setup", "t": "AUC = {{frac:FD0|ClT}} = {{frac:(0.8)(1000 mg)|1.6632 L/hr}} = 481 (mg/L)·hr", "why": "Only the absorbed fraction of an oral dose reaches the plasma, so the AUC uses F × D0, and mg ÷ (L/hr) gives (mg/L)·hr."}], "teach": [{"h": "AUC from dose and clearance", "list": ["ClT = {{frac:FD0|AUC}}, so AUC = {{frac:FD0|ClT}}.", "mg ÷ (L/hr) = (mg/L) × hr, the unit of an area under a concentration–time curve."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 2"},
{"id": "ws5-3-3", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "oral-model-equation", "skill": "conctime", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 3. Equation of the model for this drug given orally. What is the coefficient in front of the brackets?", "units": "mg/L", "answer": 34.19, "tol": 0.34, "steps": [{"k": "setup", "t": "k = {{frac:0.693|10}} = 0.0693 hr⁻¹; ka = {{frac:0.693|0.25}} = 2.772 hr⁻¹", "why": "Each rate constant is 0.693 divided by its own half-life: elimination from the 10 hr half-life, absorption from 0.25 hr."}, {"k": "algebra", "t": "Cp = {{frac:(0.8)(2.772 hr⁻¹)(1000 mg)|(24 L)(2.772 − 0.0693) hr⁻¹}} (e^(−0.0693t) − e^(−2.772t))", "why": "This is the single-dose oral equation with every value except t filled in; the coefficient comes out in mg/L."}, {"k": "round", "t": "Cp = 34.19 mg/L (e^(−0.0693t) − e^(−2.772t))", "why": "The coefficient, 34.19 mg/L, is the factor in front of the brackets; with the two exponents it is the whole model."}], "teach": [{"h": "Reading the fitted oral equation", "list": ["The fitted form is Cp = A(e^(−kt) − e^(−ka t)).", "The smaller exponent is k; the larger is ka.", "A = {{frac:F ka D0|VD(ka − k)}}, so VD = {{frac:F ka D0|A(ka − k)}}.", "Put A in mg/L before solving for a volume in litres."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 3"},
{"id": "ws5-3-4", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "peak", "concept": "cmax-oral", "skill": "oral", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 4. Cmax", "units": "mg/L", "answer": 30.32, "tol": 0.3, "steps": [{"k": "setup", "t": "tmax = {{frac:ln(2.772/0.0693)|(2.772 − 0.0693) hr⁻¹}} = 1.36 hr", "why": "Absorption here is 40 times faster than elimination, so the curve peaks early, at about an hour and a third after the dose."}, {"k": "algebra", "t": "Cmax = 34.19 mg/L (e^(−(0.0693)(1.36)) − e^(−(2.772)(1.36))) = 30.32 mg/L", "why": "Putting tmax into the model equation gives the peak concentration in mg/L, the unit of the coefficient."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 4"},
{"id": "ws5-3-5", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "extravasc", "concept": "c0-iv-vs-oral", "skill": "vddose", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 5. Initial plasma concentration if the dose were administered as an IV bolus dose", "units": "mg/L", "answer": 41.67, "tol": 0.42, "steps": [{"k": "setup", "t": "C0 = {{frac:D0|VD}} = {{frac:1000 mg|24 L}} = 41.67 mg/L", "why": "An IV dose enters the blood whole, so F = 1 and C0 is the dose divided by the volume: mg ÷ L = mg/L."}], "teach": [{"h": "The same dose as an IV bolus", "list": ["C0 = {{frac:D0|VD}}, with the whole dose: an IV dose is 100% available, so no F."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 5"},
{"id": "ws5-3-6", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "oral-cp-at-t", "skill": "conctime", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 6. Plasma concentration 10 hours after administration of the oral dose", "units": "mg/L", "answer": 17.1, "tol": 0.17, "steps": [{"k": "algebra", "t": "C10 = 34.19 mg/L (e^(−(0.0693)(10)) − e^(−(2.772)(10))) = 17.10 mg/L", "why": "By 10 hr the absorption term e^(−27.7) is close to 0, so the concentration is set by the elimination term alone."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 6"},
{"id": "ws5-3-7", "type": "numeric", "prof": "Mosley", "tier": "new", "exam": 2, "module": 5, "lecture": "L06", "topic": "oral", "sub": "conc", "concept": "oral-cp-at-t", "skill": "conctime", "source": "slide", "stem": "A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: 7. Plasma concentration 2 hours after administration of the oral dose", "units": "mg/L", "answer": 29.63, "tol": 0.3, "steps": [{"k": "algebra", "t": "C2 = 34.19 mg/L (e^(−(0.0693)(2)) − e^(−(2.772)(2))) = 29.63 mg/L", "why": "Two hours is just past the 1.36 hr peak, so the concentration is a little below the 30.32 mg/L maximum."}], "teach": [{"h": "Peak concentration after one oral dose", "list": ["Cp = {{frac:F ka D0|VD(ka − k)}} (e^(−k t) − e^(−ka t)).", "Cmax is that equation at t = tmax.", "Cmax is proportional to the dose: twice the dose, twice the peak, same tmax.", "A smaller k (slower elimination) gives a later and higher peak."]}], "cite": "Daily-Practice-Single-Oral-3-Solutions.pdf, page 1, part 7"},
];

/* Her worksheets as problem sets, appended to the course list of sets. */
